<script>
(function(){var key='slate-development-progress-v1',state={};try{state=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}var boxes=document.querySelectorAll('[data-task]');var phases=document.querySelectorAll('[data-phase][data-weight]');function render(){var total=0,weightTotal=0;phases.forEach(function(card){var id=card.dataset.phase,phaseBoxes=document.querySelectorAll('#dp-tasks .dp-task[data-phase="'+id+'"] input'),done=0;phaseBoxes.forEach(function(b){if(state[b.dataset.task])done++});var pct=phaseBoxes.length?Math.round(done/phaseBoxes.length*100):0;card.querySelector('.dp-bar i').style.width=pct+'%';card.querySelector('.dp-phase-pct').textContent=pct+'%';var w=Number(card.dataset.weight||0);total+=pct*w;weightTotal+=w});document.getElementById('dp-total').textContent=(weightTotal?Math.round(total/weightTotal):0)+'%';document.querySelectorAll('.dp-task').forEach(function(row){var b=row.querySelector('input');row.classList.toggle('done',!!state[b.dataset.task])})}boxes.forEach(function(b){b.addEventListener('change',function(){state[b.dataset.task]=b.checked;localStorage.setItem(key,JSON.stringify(state));render()})});render()})();
</script>
